DataTable.ext.type.detect.unshift(function (d) {
    return d.split("%").length == 2
        ? 'percent'
        : null;
});
 
DataTable.ext.type.order['percent-pre'] = function (d) {
    return parseFloat(d.split("%")[0]);
};

$(document).ready( function () {
    $('table.data-frame').DataTable({
    paging: false, order: [],
    colReorder: true, fixedColumns: true, scrollX: true, fixedHeader: true,
    layout: {
        topStart: {
            buttons: ['colvis']
        }
    }
    });
} );